 * Total order over sortable values: absent values first, then numbers,
 * strings, and booleans.
 * @param {unknown} a First value.
 * @param {unknown} b Second value.
 * @returns {number} Negative, zero, or positive.
 */
export function compareValues(a, b) {
  // Check for absent values
  const aAbsent = a === null || a === undefined || (typeof a === 'number' && Number.isNaN(a));
  const bAbsent = b === null || b === undefined || (typeof b === 'number' && Number.isNaN(b));

  if (aAbsent && bAbsent) return 0;
  if (aAbsent) return -1;
  if (bAbsent) return 1;

  // Both values are present, check types
  const typeA = typeof a;
  const typeB = typeof b;

  // Handle unsupported types
  const supportedTypes = ['number', 'string', 'boolean'];
  if (!supportedTypes.includes(typeA)) {
    throw new TypeError(`unsupported value type: ${typeA}`);
  }
  if (!supportedTypes.includes(typeB)) {
    throw new TypeError(`unsupported value type: ${typeB}`);
  }

  // Order by type rank: number (0), string (1), boolean (2)
  const typeRank = { number: 0, string: 1, boolean: 2 };
  const rankA = typeRank[typeA];
  const rankB = typeRank[typeB];

  if (rankA !== rankB) return rankA - rankB;

  // Same type, compare values
  switch (typeA) {
    case 'number':
      // Handle -0 and 0 as equal
      if (a === 0 && b === 0) return 0;
      return a === b ? 0 : a < b ? -1 : 1;
    case 'string':
      // Compare by Unicode code point
      const left = [...a].map(c => c.codePointAt(0));
      const right = [...b].map(c => c.codePointAt(0));
      for (let i = 0; i < Math.min(left.length, right.length); i++) {
        if (left[i] !== right[i]) return left[i] - right[i];
      }
      return left.length - right.length;
    case 'boolean':
      return (a ? 1 : 0) - (b ? 1 : 0);
    default:
      // This should never happen due to the type check above
      throw new TypeError(`unsupported value type: ${typeA}`);
  }
}

