    if (typeof spec !== 'object' || spec === null) {
      throw new TypeError('key spec must be an object');
    }
    if (typeof spec.key !== 'string' && typeof spec.key !== 'function') {
      throw new TypeError('key must be a string path or a function');
    }
    if (spec.direction !== undefined && spec.direction !== 'asc' && spec.direction !== 'desc') {
      throw new RangeError(`unknown direction: ${JSON.stringify(spec.direction)}`);
    }
    if (spec.nulls !== undefined && spec.nulls !== 'first' && spec.nulls !== 'last') {
      throw new RangeError(`unknown null placement: ${JSON.stringify(spec.nulls)}`);
    }
  }

  return (a, b) => {
    for (const spec of specs) {
      // Get values for this key
      let left, right;
      if (typeof spec.key === 'function') {
        left = spec.key(a);
        right = spec.key(b);
      } else {
        // Handle dot-separated property path
        left = spec.key.split('.').reduce((v, p) => (v == null ? undefined : v[p]), a);
        right = spec.key.split('.').reduce((v, p) => (v == null ? undefined : v[p]), b);
      }

      // Handle absent values
      const leftAbsent = left === null || left === undefined || (typeof left === 'number' && Number.isNaN(left));
      const rightAbsent = right === null || right === undefined || (typeof right === 'number' && Number.isNaN(right));

      if (leftAbsent || rightAbsent) {
        if (leftAbsent && rightAbsent) continue;
        const nullsFirst = (spec.nulls ?? 'last') === 'first';
        const absentValue = leftAbsent ? -1 : 1;
        return absentValue * (nullsFirst ? 1 : -1);
      }

      // Compare present values
      let order;
      try {
        order = compareValues(left, right);
      } catch (error) {
        // Re-throw TypeError from compareValues
